// reads value i out of an array of 6-bit values
byte read6(const unsigned char *data, unsigned int i)
{
  unsigned int bit = i * 6;
  return (pgm_read_word(data + (bit >> 3)) >> (bit & 7)) & 63;
}

// getTileType
// takes x and y in tile coordinates
// returns the tile type
unsigned char getTileType(unsigned int posX, unsigned int posY)
{
  // the map holds one nibble per block: which of the 16 blocks sits here
  byte m = pgm_read_byte(&maps[level - 1][((posX >> 3) + (posY & 0xF8)) >> 1]);
  m = (posX & 8) ? (m & 0x0F) : (m >> 4);
  // the block holds 8x8 tile types
  return read6(blocks, ((unsigned int)m << 6) + (posX & 7) + ((posY & 7) << 3));
}

void drawLevel()
{
  byte subX = mapPositionX & 7;
  byte subY = mapPositionY & 7;
  unsigned int intX = mapPositionX >> 3;
  unsigned int intY = mapPositionY >> 3;
  byte theme = 40 * ((level - 1) % 3);
  for (byte x = 0; x < (subX ? 17 : 16); x++)
  {
    for (byte y = 0; y < (subY ? 9 : 8); y++)
    {
      sprites.drawSelfMasked(((int)x << 3) - subX, ((int)y << 3) - subY, tileset, getTileType(intX + x, intY + y) + theme);
    }
  }
}

// drawNumbers
// draws a zero padded number: timer (3 digits), score (6 digits) or level (3 digits)
void drawNumbers(byte numbersX, byte numbersY, byte fontType, byte dataType)
{
  byte digits = 3;
  unsigned long value;
  if (dataType == DATA_TIMER) value = exitDoor.counter;
  else if (dataType == DATA_LEVEL) value = displayLevel;
  else
  {
    value = scorePlayer;
    digits = 6;
  }

  byte buf[6];
  for (byte i = digits; i > 0;)
  {
    buf[--i] = value % 10;
    value /= 10;
  }

  for (byte i = 0; i < digits; i++)
  {
    switch (fontType)
    {
      case FONT_TINY:
        sprites.drawSelfMasked(numbersX + (4 * i), numbersY, numbersTiny, buf[i]);
        break;
      case FONT_SMALL:
        sprites.drawPlusMask(numbersX + (7 * i), numbersY, numbersSmall_plus_mask, buf[i]);
        break;
      default:
        sprites.drawSelfMasked(numbersX + (10 * i), numbersY, numbersBig, buf[i]);
        break;
    }
  }
}

// mapCollide
// pushes a 16x16 object out of any solid tile it overlaps
void mapCollide(int& x, int& y, bool horizontal, char& vel)
{
  byte tileXMax = x % TILE_WIDTH != 0;
  byte tileYMax = y % TILE_HEIGHT != 0;
  int& pos = horizontal ? x : y;
  for (short tilex = x / TILE_WIDTH; tilex < x / TILE_WIDTH + 2 + tileXMax; tilex++)
  {
    for (short tiley = y / TILE_HEIGHT; tiley < y / TILE_HEIGHT + 2 + tileYMax; tiley++)
    {
      if (getTileType(tilex, tiley) > 10)
      {
        short tile = (horizontal ? tilex : tiley) * TILE_WIDTH;
        if (vel < 0) pos = tile + TILE_WIDTH;
        else if (vel > 0) pos = tile - 16;
        vel = 0;
      }
    }
  }
}

